import{createJungleRenderer as createInteriorRenderer}from'./jungle-renderer.mjs';
export function createLazyJungleRenderer(resources,{document:doc=globalThis.document}={}){let jungle=null,actor=null,ag=null;const canvases=[];
const releaseInterior=()=>{jungle=null;for(const c of canvases)c.width=c.height=1;canvases.length=0};
const releaseHub=()=>{if(actor)actor.width=actor.height=1;actor=ag=null};
const draw=(g,options={})=>{const s=options.state;if(s.scene!=='geojeeup-v1'){if(!resources.jungle.presentationReady)throw Error('JUNGLE_PRESENTATION_NOT_READY');jungle??=createInteriorRenderer(resources,{document:{createElement(tag){const c=doc.createElement(tag);canvases.push(c);return c}}});return jungle(g,options)}
const sprite=resources.jungle.getHubPlayerSprite();if(!actor){actor=doc.createElement('canvas');actor.width=107;actor.height=107;ag=actor.getContext('2d');}
const[x,y]=s.foot,cam=[Math.max(0,Math.min(2696,x-480)),Math.max(0,Math.min(1252,y-360))],time=options.elapsedMs??0;const r=resources.hub.render({camera:[...cam,960,540],minutes:options.minutes??720,state:s.townState,ms:time,rest:!options.moving});const pixels=g.createImageData(960,540);pixels.data.set(r.pixels);g.putImageData(pixels,0,0);const drawHarin=()=>g.drawImage(resources.hub.items['harin-left-idle.png'],0,0,256,256,3188-54-cam[0],536-90-cam[1],107,107);if(y>=536)drawHarin();ag.clearRect(0,0,107,107);const row={down:0,right:1,left:2,up:3}[s.facing],frame=options.moving?Math.floor(time/160)%3:0;ag.drawImage(sprite,frame*256,row*256,256,256,0,0,107,107);g.drawImage(actor,x-53-cam[0],y-90-cam[1]);if(y<536)drawHarin();return{camera:cam,clockMs:time,scene:'geojeeup-v1',townState:s.townState,originalEnvironment:true}};draw.releaseInterior=releaseInterior;draw.releaseHub=releaseHub;draw.dispose=()=>{releaseInterior();releaseHub()};return draw;}
